                  date_text=v['date'] or None, time_text=v['time'] or None,
                  text=words, span=None, qid=None)
        evs.append(ev)
    vars['engine_events'] = json.dumps(evs)
except Exception:
    vars['engine_events'] = json.dumps([dict(kind='other')])
